// ============================================================
// Build GitHub GraphQL query with dynamic date range (past 7 days)
// ============================================================

const repoOwner = $json.repoOwner || 'claude-builders-bounty';
const repoName  = $json.repoName  || 'claude-builders-bounty';

// Calculate the date 7 days ago for the "since" filter
const now       = new Date();
const pastDate  = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceISO  = pastDate.toISOString();

const graphqlQuery = `
  query {
    repository(owner: "${repoOwner}", name: "${repoName}") {
      defaultBranchRef {
        target {
          ... on Commit {
            history(since: "${sinceISO}") {
              totalCount
              nodes {
                oid
                messageHeadline
                committedDate
                author {
                  name
                  user {
                    login
                  }
                }
              }
            }
          }
        }
      }
      issues(
        first: 50
        states: CLOSED
        orderBy: {field: UPDATED_AT, direction: DESC}
      ) {
        totalCount
        nodes {
          number
          title
          state
          closedAt
          closedBy {
            login
          }
          labels(first: 5) {
            nodes {
              name
            }
          }
        }
      }
      pullRequests(
        first: 50
        states: MERGED
        orderBy: {field: UPDATED_AT, direction: DESC}
      ) {
        totalCount
        nodes {
          number
          title
          state
          mergedAt
          mergedBy {
            login
          }
          labels(first: 5) {
            nodes {
              name
            }
          }
        }
      }
    }
  }
`;

return [{
  graphqlBody: {
    query: graphqlQuery
  },
  repoOwner: repoOwner,
  repoName: repoName
}];

// ============================================================
// Transform GitHub API response into Claude prompt
// ============================================================

const data     = $input.first().json;
const language = $json.language || 'EN';
const repo     = `${$json.repoOwner || 'claude-builders-bounty'}/${$json.repoName || 'claude-builders-bounty'}`;

// Extract commit data
const repoData    = data?.data?.repository || {};
const commits     = repoData?.defaultBranchRef?.target?.history?.nodes || [];
const totalCommits= repoData?.defaultBranchRef?.target?.history?.totalCount || 0;
const issues      = repoData?.issues?.nodes || [];
const totalIssues = repoData?.issues?.totalCount || 0;
const prs         = repoData?.pullRequests?.nodes || [];
const totalPRs    = repoData?.pullRequests?.totalCount || 0;

// Format commit list
const commitLines = commits
  .map(c => `- ${c.messageHeadline} (${c.author?.user?.login || c.author?.name || 'unknown'})`)
  .join('\n');

// Format issue list
const issueLines = issues
  .map(i => {
    const labels = i.labels?.nodes?.map(l => `[${l.name}]`).join(' ') || '';
    const closedBy = i.closedBy?.login ? ` @${i.closedBy.login}` : '';
    return `- #${i.number} ${i.title}${closedBy} ${labels}`.trim();
  })
  .join('\n');

// Format PR list
const prLines = prs
  .map(p => {
    const labels = p.labels?.nodes?.map(l => `[${l.name}]`).join(' ') || '';
    const mergedBy = p.mergedBy?.login ? ` @${p.mergedBy.login}` : '';
    return `- #${p.number} ${p.title}${mergedBy} ${labels}`.trim();
  })
  .join('\n');

const today = new Date().toISOString().slice(0, 10);

let prompt;
if (language === 'FR') {
  prompt = `Tu es un rédacteur technique qui génère un résumé hebdomadaire concis pour le dépôt GitHub ${repo}.

Résumé de la semaine (${today}) :

---
**Commits (${totalCommits})** :
${commitLines || 'Aucun commit cette semaine.'}

**Issues fermées (${totalIssues})** :
${issueLines || 'Aucune issue fermée cette semaine.'}

**Pull Requests fusionnées (${totalPRs})** :
${prLines || 'Aucune PR fusionnée cette semaine.'}
---

Génère un résumé narratif en français de 3 à 5 paragraphes qui met en évidence les principaux changements, corrections de bugs et avancements. Structure-le ainsi :
1. Vue d'ensemble de la semaine (ton général)
2. Changements et nouvelles fonctionnalités
3. Corrections de bugs et maintenance
4. Conclusion / prochaines étapes

Sois concis mais informatif. Termine par un émoji ✨.`;
} else {
  prompt = `You are a technical writer generating a concise weekly summary for the GitHub repository ${repo}.

This week's data (${today}) :

---
**Commits (${totalCommits})** :
${commitLines || 'No commits this week.'}

**Closed Issues (${totalIssues})** :
${issueLines || 'No issues closed this week.'}

**Merged Pull Requests (${totalPRs})** :
${prLines || 'No PRs merged this week.'}
---

Generate a narrative summary in English of 3 to 5 paragraphs highlighting the key changes, bug fixes, and progress. Structure it as:
1. Overall week overview (tone)
2. Changes and new features
3. Bug fixes and maintenance
4. Conclusion / next steps

Be concise but informative. End with an emoji ✨.`;
}

return [{
  prompt: prompt,
  claudeBody: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 2048,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ]
  }
}];
